export interface ConnectorConfig {
  /** Brevo API key for authentication */
  brevoApiKey: string
  /** Brevo list ID to subscribe the contact to */
  brevoListId: number
  /** Optional custom fetch implementation for testing */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    response_id: string
    submitted_at: string
    answers: Array<{
      field: {
        id: string
        type: string
      }
      type: string
      email?: string
      text?: string
      [key: string]: unknown
    }>
    hidden: Record<string, unknown>
    landed_at: string
    calculated: Record<string, unknown>
    metadata: Record<string, unknown>
  }
}

export interface HandleResult {
  contactId: number
  email: string
  listId: number
}

function extractAnswerValue(answers: TypeformWebhookPayload['form_response']['answers'], fieldId: string): string | undefined {
  const answer = answers.find(a => a.field.id === fieldId)
  if (!answer) return undefined
  if (answer.type === 'email') return answer.email
  if (answer.type === 'text') return answer.text
  return String(answer[answer.type])
}

export async function handle(payload: TypeformWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  const { brevoApiKey, brevoListId, fetch = globalThis.fetch } = config

  if (!brevoApiKey) throw new Error('Missing required config: brevoApiKey')
  if (typeof brevoListId !== 'number') throw new Error('Missing required config: brevoListId (number)')

  const formResponse = payload.form_response
  if (!formResponse) throw new Error('Invalid payload: missing form_response')

  const email = extractAnswerValue(formResponse.answers, 'field_email')
  const firstName = extractAnswerValue(formResponse.answers, 'field_first_name')
  const lastName = extractAnswerValue(formResponse.answers, 'field_last_name')

  if (!email) throw new Error('Required field missing: email (field_email)')

  const attributes: Record<string, string> = {}
  if (firstName) attributes.FIRSTNAME = firstName
  if (lastName) attributes.LASTNAME = lastName

  const body = {
    email,
    attributes,
    listIds: [brevoListId],
    updateEnabled: true,
    ext_id: formResponse.response_id
  }

  const response = await fetch('https://api.brevo.com/v3/contacts', {
    method: 'POST',
    headers: {
      'api-key': brevoApiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Brevo API error: ${response.status} ${response.statusText} at POST https://api.brevo.com/v3/contacts - ${text}`)
  }

  const data = await response.json<{ id: number }>()
  return {
    contactId: data.id,
    email,
    listId: brevoListId
  }
}

